import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // 读入测试用例个数
        int T = sc.nextInt();
        while(T-- > 0) {
            int n = sc.nextInt();
            long k = sc.nextLong();

            // 求 n 的因子列表，使用 ArrayList 存储
            ArrayList<Integer> factors = new ArrayList<>();
            for (int x = 1; x * x <= n; x++) {
                if(n % x == 0) {
                    factors.add(x);
                    if(x != n / x) {
                        factors.add(n / x);
                    }
                }
            }
            // 对因子列表排序
            Collections.sort(factors);

            int i = 0;  // 已遍历的因子个数
            boolean found = false;
            for (int f : factors) {
                i++;
                // 区间 [1, f] 内非因子数为 f - i
                if (f - i >= k) {
                    // 第 k 个非因子数为 i + k - 1
                    System.out.println(i + k - 1);
                    found = true;
                    break;
                }
            }
            // 如果在因子区间内没有找到答案，则答案在 n 后面
            if (!found) {
                System.out.println(i + k);
            }
        }
        sc.close();
    }
}
