### Python

```python
import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    q = int(data[0])
    idx = 1
    out_lines = []
    for _ in range(q):
        x = int(data[idx]); y = int(data[idx+1]); idx += 2
        # 求 x 的所有除数
        divisors = []
        i = 1
        while i * i <= x:
            if x % i == 0:
                divisors.append(i)
                if i != x // i:
                    divisors.append(x // i)
            i += 1
        divisors.sort()
        cnt = 0
        found = False
        for d in divisors:
            cnt += 1
            if d - cnt >= y:
                out_lines.append(str(cnt + y - 1))
                found = True
                break
        if not found:
            out_lines.append(str(cnt + y))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
```

